import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Edge case: empty item list ---
  it.todo("empty item list -> premium 5 G (only processing fee)");

  // --- Base premiums for main items (single item, no modifiers, newcomer 0 years) ---
  // Note: a single-item quote for a newcomer includes first-insurance surcharge and processing fee.
  // We keep base-premium tests focused via zero-year new customer known amounts.

  // --- Building block of 3 alike components (base premium in isolation) ---
  it.todo("2 runes -> 50 G base premium");
  it.todo("3 runes -> 60 G base premium (block applies)");
  it.todo("4 runes -> 100 G base premium (no block, block requires exactly 3)");
  it.todo("7 runes -> 175 G base premium");

  // --- 'Alike' components ---
  it.todo("2 runes + 1 moonstone -> 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones -> 120 G base premium (two separate blocks)");

  // --- Modifier scope on multi-item policies ---
  it.todo("cursed sword + plain amulet -> 210 G before further modifiers and fee");

  // --- Modifier thresholds ---
  it.todo("customer with exactly 2 years -> loyalty discount applies");
  it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge applies");
  it.todo("cursed sword with enchantment 5 -> both surcharges apply");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge");

  // --- Integration examples ---
  it.todo("newcomer with a cursed sword -> premium 165 G");
  it.todo("long-standing customer's second contract cursed sword ench 7 -> premium 160 G");

  // --- Rounding ---
  it.todo("premium yielding 197.5 G -> final premium 198 G (rounded up)");

  // --- Standard reimbursement (claims) ---
  it.todo("regular sword (steel, ench 3), damage 500 G -> payout 400 G");
  it.todo("damage to a rune (value 250 G), damage 200 G -> payout 100 G");

  // --- Enchantment threshold clause ---
  it.todo("steel sword, enchantment 9, damage 1000 G -> payout 400 G (50% then deductible)");

  // --- Dragon material clause ---
  it.todo("dragon-material sword, enchantment 5, damage 800 G -> payout 700 G (full then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G -> payout 400 G (50% wins)");
  it.todo("dragon-material sword, enchantment 8, damage 1000 G -> payout 400 G (high-ench applies)");

  // --- Deductible per damage event ---
  it.todo("dragon attack damages sword (500) and amulet (300) -> payout 600 G (deductible once per item)");

  // --- Payout rounding ---
  it.todo("payout yielding 350.5 G -> final payout 350 G (rounded down)");

  // --- Multiple items of the same type ---
  it.todo("policy covers two swords -> insurance sum 2000 G, cap 4000 G; both damaged -> separate deductibles");
  it.todo("more damage entries of a type than covered -> claim rejected (non-zero exit)");

  // --- Cap ---
  it.todo("sword and amulet -> insurance sum 1600 G, cap 3200 G");
  it.todo("cursed sword -> cap 2000 G (based on unmodified insurance value)");
  it.todo("sword + 3 runes block -> insurance sum 1750 G");
  it.todo("cap exhaustion: two successive 1500 G claims -> 1400 then 600, remaining 0");

  // --- Error edge cases ---
  it.todo("quote with unknown item type -> error thrown");
  it.todo("claim references item not in policy -> error thrown");
  it.todo("claim with negative amount -> error thrown");
});

