const PROCESSING_FEE = 5;
const FIRST_INSURANCE_RATE = 0.1;
const LOYALTY_RATE = 0.2;
const LOYALTY_YEARS = 2;

type QuoteStep = {
  op: "quote";
  items: { type: string; cursed?: boolean; enchantment?: number }[];
};
type Customer = { yearsWithMHPCO: number };
type Scenario = { customer: Customer; steps: QuoteStep[] };

const quotePremium = (customer: Customer, items: QuoteStep["items"]): number => {
  const policyBase = itemsPremiumBeforePolicyModifiers(items);
  let premium = policyBase;
  premium += policyBase * FIRST_INSURANCE_RATE;
  if (customer.yearsWithMHPCO >= LOYALTY_YEARS) {
    premium -= policyBase * LOYALTY_RATE;
  }
  premium += PROCESSING_FEE;
  return Math.ceil(premium);
};

export const runScenario = (scenario: Scenario): { results: unknown[] } => {
  const results = scenario.steps.map((step) =>
    ({ premium: quotePremium(scenario.customer, step.items) }),
  );
  return { results };
};

