const PROCESSING_FEE = 5;
const FIRST_INSURANCE_RATE = 0.1;
const LOYALTY_RATE = 0.2;
const LOYALTY_YEARS = 2;
const FOLLOWUP_DISCOUNT_RATE = 0.15;

type QuoteStep = {
  op: "quote";
  items: MainItem[];
};
type Customer = { yearsWithMHPCO: number };
type Scenario = { customer: Customer; steps: QuoteStep[] };

const quotePremium = (
  customer: Customer,
  items: MainItem[],
  isFollowUpContract: boolean,
): number => {
  const itemsWithSurcharges = itemsPremiumBeforePolicyModifiers(items);
  const modifierBase = sum(items.map(rawBasePremium));
  const isLoyal = customer.yearsWithMHPCO >= LOYALTY_YEARS;
  const firstInsuranceSurcharge = modifierBase * FIRST_INSURANCE_RATE;
  const loyaltyDiscount = isLoyal ? modifierBase * LOYALTY_RATE : 0;
  const followUpDiscount = isFollowUpContract
    ? modifierBase * FOLLOWUP_DISCOUNT_RATE
    : 0;
  const premium =
    itemsWithSurcharges +
    firstInsuranceSurcharge -
    loyaltyDiscount -
    followUpDiscount +
    PROCESSING_FEE;
  return Math.ceil(premium);
};

export const runScenario = (scenario: Scenario): { results: unknown[] } => {
  const results = scenario.steps.map((step, index) =>
    ({ premium: quotePremium(scenario.customer, step.items, index > 0) }),
  );
  return { results };
};

