input.newString:
type QuoteStep = {
  op: "quote";
  items: MainItem[];
};
type Damage = { itemType: string; amount: number };
type ClaimStep = {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
};
type Step = QuoteStep | ClaimStep;
type Customer = { yearsWithMHPCO: number };
type Scenario = { customer: Customer; steps: Step[] };

const MAIN_ITEM_INSURANCE_VALUE: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
};

const DEDUCTIBLE = 100;
const CAP_MULTIPLIER = 2;

const quotePremium = (
  customer: Customer,
  items: MainItem[],
  isFollowUpContract: boolean,
): number => {
  const itemsWithSurcharges = itemsPremiumBeforePolicyModifiers(items);
  const modifierBase = sum(items.map(rawBasePremium));
  const policyAdjustment = (rate: number, applies: boolean): number =>
    surcharge(modifierBase, rate, applies);

  const isLoyal = customer.yearsWithMHPCO >= LOYALTY_YEARS;
  const firstInsuranceSurcharge = policyAdjustment(FIRST_INSURANCE_RATE, true);
  const loyaltyDiscount = policyAdjustment(LOYALTY_RATE, isLoyal);
  const followUpDiscount = policyAdjustment(
    FOLLOWUP_DISCOUNT_RATE,
    isFollowUpContract,
  );

  const premium =
    itemsWithSurcharges +
    firstInsuranceSurcharge -
    loyaltyDiscount -
    followUpDiscount +
    PROCESSING_FEE;
  return roundPremium(premium);
};

type Policy = { items: MainItem[]; remainingCap: number };

const insuranceSum = (items: MainItem[]): number =>
  sum(items.map((item) => MAIN_ITEM_INSURANCE_VALUE[item.type]));

const payoutForDamage = (damage: Damage): number =>
  damage.amount - DEDUCTIBLE;

export const runScenario = (scenario: Scenario): { results: unknown[] } => {
  const policies: Policy[] = [];
  let quoteCount = 0;
  const results = scenario.steps.map((step) => {
    if (step.op === "quote") {
      const premium = quotePremium(
        scenario.customer,
        step.items,
        quoteCount > 0,
      );
      quoteCount += 1;
      policies.push({
        items: step.items,
        remainingCap: insuranceSum(step.items) * CAP_MULTIPLIER,
      });
      return { premium };
    }
    const policy = policies[step.policy];
    const payout = sum(step.incident.damages.map(payoutForDamage));
    policy.remainingCap -= payout;
    return { payout, remainingCap: policy.remainingCap };
  });
  return { results };
};

